def hasPathSum(root, t):
    if not root:
        return False
    st = [(root, root.val)]
    while st:
        n, s = st.pop()
        if not n.left and not n.right and s == t:
            return True
        if n.left:
            st.append((n.left, s + n.left.val))
        if n.right:
            st.append((n.right, s + n.right.val))
    return False

